WITH prometheus_query_step_1 AS (SELECT timeSeriesIdToGroup(id) AS group, samples FROM timeSeriesSelector('default', 'ts', 'metric_0', toDateTime64(toDecimal128('1793505300.001', 3), 3), toDateTime64(toDecimal128('1793505600', 3), 3), 'samples')), prometheus_query_step_2 AS (SELECT group, CAST(timeSeriesLastToGrid(toDateTime64(toDecimal128('1793505600', 3), 3), toDateTime64(toDecimal128('1793505600', 3), 3), toDecimal64('0', 3), toDecimal64('300', 3))(samples), 'Array(Nullable(Float64))') AS `values` FROM prometheus_query_step_1 GROUP BY group), prometheus_query_step_3 AS (SELECT group, arrayMap(lambda(tuple(x), if(and(isNotNull(x), equals(reinterpretAsUInt64(assumeNotNull(x)), 9218868437227405314)), NULL, x)), `values`) AS `values` FROM prometheus_query_step_2), prometheus_query_step_4 AS (SELECT group, `values` FROM prometheus_query_step_3 WHERE arrayExists(lambda(tuple(x), isNotNull(x)), `values`)), prometheus_query_step_5 AS (SELECT group, arrayMap(lambda(tuple(x), abs(x)), `values`) AS `values` FROM prometheus_query_step_4), prometheus_query_step_6 AS (SELECT timeSeriesRemoveTag(group, '__name__') AS new_group, `values` FROM prometheus_query_step_5), prometheus_query_step_7 AS (SELECT new_group AS group, `values` FROM prometheus_query_step_6), prometheus_query_step_8 AS (SELECT CAST(0, 'UInt64') AS new_group, sumForEach(`values`) AS `values` FROM prometheus_query_step_7), prometheus_query_step_9 AS (SELECT new_group AS group, `values` FROM prometheus_query_step_8 WHERE notEmpty(`values`)) SELECT timeSeriesGroupToTags(group) AS tags, toDateTime64(toDecimal128('1793505600', 3), 3) AS timestamp, toFloat64(assumeNotNull(arrayElement(`values`, 1))) AS value FROM prometheus_query_step_9 WHERE isNotNull(arrayElement(`values`, 1)) ORDER BY tags ASC
